/*
 * index.jsx — faithful React conversion of ttmip/web/index.html (TTMIP v8).
 *
 * Generated from the original single-file dashboard. The exact CSS and body
 * markup are preserved; the original imperative dashboard logic (and the API
 * client) run inside a useEffect after mount, so every chart, map, ticker, tab,
 * and the API hydration behave identically to index.html.
 *
 * Usage:
 *   import TTMIPIndex from './index.jsx';
 *   <TTMIPIndex />
 *
 * Notes:
 * - Mounts the original markup verbatim via dangerouslySetInnerHTML; the bundled
 *   script attaches all behaviour via getElementById (as in the source).
 * - Loads Google Fonts into <head> on mount.
 * - For a component-idiomatic React port instead, see ../web-react/.
 */
import { useEffect, useRef } from 'react';

const CSS = ":root {\n  --bg:#07090D; --surface:#0C1118; --panel:#111923; --panel2:#141F2B;\n  --border:#192433; --border2:#1F3044;\n  --accent:#E8873A; --accent2:#F4A233; --accent3:#FBC05A;\n  --green:#1A9E5F; --green2:#22C97A; --green3:#A8F5D0;\n  --red:#D94040; --red2:#FF6060;\n  --blue:#2272C3; --blue2:#3A9FE8; --blue3:#A8D8FF;\n  --purple:#7B52C8; --purple2:#A07EEF;\n  --teal:#0DA88C; --teal2:#1ECFB0;\n  --gold:#D4A22A; --gold2:#F5C842;\n  --cam-green:#007A5E; --cam-red:#CE1126; --cam-yellow:#FCD116;\n  --text:#D6E4F0; --text2:#6A91B0; --text3:#2E4A62; --text4:#1A3347;\n}\n*{box-sizing:border-box;margin:0;padding:0;}\nhtml{scroll-behavior:smooth;}\nbody{background:var(--bg);font-family:'IBM Plex Sans',sans-serif;color:var(--text);overflow-x:hidden;min-height:100vh;}\nbody::after{content:'';position:fixed;inset:0;background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,0,0,0.018) 3px,rgba(0,0,0,0.018) 4px);pointer-events:none;z-index:9000;}\n\n/* SCROLLBAR */\n::-webkit-scrollbar{width:3px;height:3px;}\n::-webkit-scrollbar-track{background:transparent;}\n::-webkit-scrollbar-thumb{background:var(--border2);border-radius:4px;}\n\n/* TOPBAR */\n.topbar{background:var(--surface);border-bottom:1px solid var(--border);display:flex;align-items:center;justify-content:space-between;padding:0 20px;height:52px;position:sticky;top:0;z-index:500;}\n.logo{display:flex;align-items:center;gap:10px;}\n.logo-badge{width:30px;height:30px;background:linear-gradient(135deg,var(--cam-green) 0%,var(--cam-red) 100%);border-radius:7px;display:flex;align-items:center;justify-content:center;font-family:'Syne',sans-serif;font-weight:800;font-size:11px;}\n.logo-text{font-family:'Syne',sans-serif;font-weight:700;font-size:13.5px;letter-spacing:0.01em;}\n.logo-sub{font-size:9px;color:var(--text3);letter-spacing:0.09em;text-transform:uppercase;font-family:'DM Mono',monospace;}\n.nav-tabs{display:flex;gap:2px;}\n.nav-tab{padding:5px 11px;border-radius:5px;font-size:11.5px;font-weight:500;cursor:pointer;border:1px solid transparent;transition:all 0.15s;color:var(--text2);user-select:none;}\n.nav-tab:hover{color:var(--text);background:var(--panel);}\n.nav-tab.active{background:rgba(232,135,58,0.13);color:var(--accent);border-color:rgba(232,135,58,0.22);font-weight:600;}\n.nav-tab.reg-tab.active{background:rgba(123,82,200,0.13);color:var(--purple2);border-color:rgba(123,82,200,0.22);}\n.topbar-right{display:flex;align-items:center;gap:10px;}\n.live-badge{display:flex;align-items:center;gap:5px;background:rgba(34,201,122,0.09);border:1px solid rgba(34,201,122,0.2);border-radius:20px;padding:4px 10px;font-size:10px;color:var(--green2);font-family:'DM Mono',monospace;}\n.live-dot{width:5px;height:5px;background:var(--green2);border-radius:50%;animation:blink 1.5s infinite;}\n@keyframes blink{0%,100%{opacity:1;}50%{opacity:0.3;}}\n.icon-btn{width:32px;height:32px;background:var(--panel);border:1px solid var(--border2);border-radius:6px;display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:14px;position:relative;transition:all 0.15s;}\n.icon-btn:hover{border-color:var(--accent);}\n.badge-dot{position:absolute;top:-4px;right:-4px;background:var(--red);width:15px;height:15px;border-radius:50%;font-size:8px;display:flex;align-items:center;justify-content:center;font-weight:700;font-family:'DM Mono',monospace;border:2px solid var(--bg);}\n.user-chip{display:flex;align-items:center;gap:7px;background:var(--panel);border:1px solid var(--border2);border-radius:20px;padding:3px 10px 3px 3px;cursor:pointer;transition:all 0.15s;}\n.user-chip:hover{border-color:var(--accent);}\n.user-av{width:24px;height:24px;border-radius:50%;background:linear-gradient(135deg,var(--accent),var(--purple));display:flex;align-items:center;justify-content:center;font-size:9px;font-weight:700;}\n\n/* TICKER */\n.ticker-bar{background:var(--surface);border-bottom:1px solid var(--border);padding:4px 20px;overflow:hidden;white-space:nowrap;}\n.ticker-inner{display:inline-flex;gap:28px;animation:tick 60s linear infinite;}\n@keyframes tick{0%{transform:translateX(0);}100%{transform:translateX(-50%);}}\n.ticker-item{display:inline-flex;align-items:center;gap:5px;font-size:9.5px;font-family:'DM Mono',monospace;}\n.tn{color:var(--text2);}.tp{color:var(--text);font-weight:500;}.tc{font-size:9px;}\n.tc.up{color:var(--green2);}.tc.dn{color:var(--red2);}\n\n/* LAYOUT */\n.layout{display:grid;grid-template-columns:205px 1fr;min-height:calc(100vh - 52px - 36px);}\n\n/* SIDEBAR */\n.sidebar{background:var(--surface);border-right:1px solid var(--border);padding:14px 0;overflow-y:auto;}\n.sidebar-label{font-size:8.5px;font-weight:700;letter-spacing:0.16em;text-transform:uppercase;color:var(--text3);padding:10px 13px 4px;font-family:'DM Mono',monospace;}\n.sidebar-item{display:flex;align-items:center;gap:8px;padding:7px 10px;font-size:12px;font-weight:500;color:var(--text2);cursor:pointer;transition:all 0.13s;margin:1px 7px;border-radius:6px;user-select:none;border:1px solid transparent;}\n.sidebar-item:hover{background:var(--panel);color:var(--text);}\n.sidebar-item.active{background:rgba(232,135,58,0.1);color:var(--accent);border-color:rgba(232,135,58,0.18);}\n.sidebar-item.reg-item.active{background:rgba(123,82,200,0.1);color:var(--purple2);border-color:rgba(123,82,200,0.18);}\n.s-icon{font-size:13px;width:16px;text-align:center;}\n.s-badge{margin-left:auto;background:var(--red);color:#fff;font-size:8.5px;font-weight:700;padding:2px 5px;border-radius:8px;font-family:'DM Mono',monospace;}\n.s-badge.warn{background:var(--accent2);color:#000;}\n.s-badge.purple{background:var(--purple);color:#fff;}\nhr.sdiv{border:none;border-top:1px solid var(--border);margin:7px 11px;}\n.sp-grid{display:grid;grid-template-columns:1fr 1fr;gap:3px;padding:4px 10px 10px;}\n.sp-pill{background:var(--panel);border:1px solid var(--border);border-radius:3px;padding:3px 6px;font-size:8.5px;color:var(--text2);font-family:'DM Mono',monospace;cursor:pointer;transition:all 0.13s;user-select:none;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}\n.sp-pill:hover{border-color:var(--text3);color:var(--text);}\n.sp-pill.active{border-color:var(--accent);color:var(--accent);background:rgba(232,135,58,0.07);}\n.src-dot{width:6px;height:6px;border-radius:50%;flex-shrink:0;}\n.src-dot.green{background:var(--green2);}\n.src-dot.yellow{background:var(--accent2);}\n.src-dot.red{background:var(--red);}\n\n/* MAIN */\n.main{padding:18px 20px;display:flex;flex-direction:column;gap:16px;overflow-x:hidden;}\n.tab-page{display:none;flex-direction:column;gap:16px;}\n.tab-page.active{display:flex;}\n.page-header{display:flex;align-items:flex-end;justify-content:space-between;}\n.page-title{font-family:'Syne',sans-serif;font-size:20px;font-weight:800;letter-spacing:-0.02em;}\n.page-subtitle{font-size:11px;color:var(--text3);margin-top:3px;}\n.time-range{display:flex;gap:2px;background:var(--panel);border:1px solid var(--border);border-radius:6px;padding:3px;}\n.tr-btn{padding:4px 10px;border-radius:4px;font-size:10.5px;font-weight:600;cursor:pointer;transition:all 0.13s;color:var(--text2);font-family:'DM Mono',monospace;user-select:none;}\n.tr-btn.active{background:var(--accent);color:#fff;}\n\n/* KPI */\n.kpi-row{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;}\n.kpi-card{background:var(--panel);border:1px solid var(--border);border-radius:10px;padding:14px 16px;position:relative;overflow:hidden;transition:transform 0.18s,box-shadow 0.18s;cursor:pointer;user-select:none;}\n.kpi-card:hover{transform:translateY(-3px);box-shadow:0 10px 28px rgba(0,0,0,0.45);}\n.kpi-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;border-radius:10px 10px 0 0;}\n.kpi-card.orange::before{background:linear-gradient(90deg,var(--accent),var(--accent2));}\n.kpi-card.green::before{background:linear-gradient(90deg,var(--green),var(--green2));}\n.kpi-card.blue::before{background:linear-gradient(90deg,var(--blue),var(--blue2));}\n.kpi-card.red::before{background:linear-gradient(90deg,var(--red),var(--red2));}\n.kpi-card.purple::before{background:linear-gradient(90deg,var(--purple),var(--purple2));}\n.kpi-label{font-size:9px;color:var(--text3);font-weight:700;letter-spacing:0.12em;text-transform:uppercase;font-family:'DM Mono',monospace;margin-bottom:7px;}\n.kpi-value{font-family:'Syne',sans-serif;font-size:24px;font-weight:800;line-height:1;letter-spacing:-0.03em;margin-bottom:6px;}\n.kpi-meta{display:flex;align-items:center;gap:5px;font-size:10px;color:var(--text2);}\n.kpi-chg{font-size:9.5px;font-weight:700;padding:2px 5px;border-radius:3px;font-family:'DM Mono',monospace;}\n.kpi-chg.up{background:rgba(34,201,122,0.13);color:var(--green2);}\n.kpi-chg.dn{background:rgba(217,64,64,0.13);color:var(--red2);}\n.kpi-icon{position:absolute;right:12px;bottom:10px;font-size:26px;opacity:0.18;}\n\n/* CARDS */\n.card{background:var(--panel);border:1px solid var(--border);border-radius:10px;overflow:hidden;}\n.card-header{display:flex;align-items:center;justify-content:space-between;padding:11px 15px;border-bottom:1px solid var(--border);}\n.card-title{font-family:'Syne',sans-serif;font-size:12px;font-weight:700;}\n.card-actions{display:flex;gap:4px;align-items:center;}\n.chip{background:var(--surface);border:1px solid var(--border);border-radius:4px;padding:3px 8px;font-size:9.5px;font-weight:600;color:var(--text3);cursor:pointer;transition:all 0.13s;font-family:'DM Mono',monospace;user-select:none;}\n.chip:hover{border-color:var(--text3);color:var(--text);}\n.chip.active{border-color:var(--accent);color:var(--accent);background:rgba(232,135,58,0.08);}\n.chip.purple{border-color:var(--purple);color:var(--purple2);background:rgba(123,82,200,0.08);}\n.card-body{padding:13px 15px;}\n\n/* GRIDS */\n.g2{display:grid;grid-template-columns:1fr 1fr;gap:14px;}\n.g3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px;}\n.g21{display:grid;grid-template-columns:2fr 1fr;gap:14px;}\n.g31{display:grid;grid-template-columns:3fr 1fr;gap:14px;}\n.g12{display:grid;grid-template-columns:1fr 2fr;gap:14px;}\n.g211{display:grid;grid-template-columns:2fr 1fr 1fr;gap:14px;}\n.g121{display:grid;grid-template-columns:1fr 2fr 1fr;gap:14px;}\n\n/* STATUS BADGES */\n.sbadge{display:inline-flex;align-items:center;padding:2px 7px;border-radius:3px;font-size:9px;font-weight:700;font-family:'DM Mono',monospace;}\n.sbadge.green{background:rgba(34,201,122,0.12);color:var(--green2);border:1px solid rgba(34,201,122,0.18);}\n.sbadge.yellow{background:rgba(244,162,51,0.12);color:var(--accent2);border:1px solid rgba(244,162,51,0.18);}\n.sbadge.red{background:rgba(217,64,64,0.12);color:var(--red2);border:1px solid rgba(217,64,64,0.18);}\n.sbadge.blue{background:rgba(58,159,232,0.12);color:var(--blue2);border:1px solid rgba(58,159,232,0.18);}\n.sbadge.purple{background:rgba(123,82,200,0.12);color:var(--purple2);border:1px solid rgba(123,82,200,0.18);}\n.sbadge.gold{background:rgba(212,162,42,0.12);color:var(--gold2);border:1px solid rgba(212,162,42,0.18);}\n.sbadge.teal{background:rgba(30,207,176,0.12);color:var(--teal2);border:1px solid rgba(30,207,176,0.18);}\n\n/* TABLES */\n.data-table{width:100%;font-size:11px;border-collapse:collapse;}\n.data-table th{text-align:left;font-size:8.5px;font-weight:700;color:var(--text3);letter-spacing:0.11em;text-transform:uppercase;padding:6px 8px;border-bottom:1px solid var(--border);font-family:'DM Mono',monospace;white-space:nowrap;position:sticky;top:0;background:var(--panel);z-index:2;}\n.data-table td{padding:6px 8px;border-bottom:1px solid rgba(25,36,51,0.7);vertical-align:middle;}\n.data-table tr{cursor:pointer;transition:background 0.1s;}\n.data-table tr:hover td{background:rgba(255,255,255,0.02);}\n.data-table tr:last-child td{border-bottom:none;}\n.tscroll{overflow-y:auto;max-height:320px;}\n\n/* BAR CHART */\n.bar-chart{display:flex;flex-direction:column;gap:8px;}\n.bar-row{display:flex;align-items:center;gap:8px;}\n.bar-label{font-size:9.5px;color:var(--text2);flex-shrink:0;font-family:'DM Mono',monospace;}\n.bar-track{flex:1;height:8px;background:var(--border);border-radius:5px;overflow:hidden;cursor:pointer;}\n.bar-fill{height:100%;border-radius:5px;transition:width 0.9s cubic-bezier(.4,0,.2,1);}\n.bar-val{font-size:9.5px;font-weight:600;color:var(--text2);width:52px;text-align:right;font-family:'DM Mono',monospace;flex-shrink:0;}\n\n/* GAUGE */\n.gauge-ring{position:relative;width:64px;height:64px;}\n.gauge-svg{transform:rotate(-90deg);}\n.gauge-track{fill:none;stroke:var(--border);stroke-width:7;}\n.gauge-fill{fill:none;stroke-width:7;stroke-linecap:round;transition:stroke-dashoffset 1.3s cubic-bezier(.4,0,.2,1);}\n.gauge-center{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-family:'Syne',sans-serif;font-size:14px;font-weight:800;}\n\n/* MAP */\n.map-container{position:relative;background:#060D14;border-radius:7px;overflow:hidden;}\n.map-alert-dot{position:absolute;border-radius:50%;cursor:pointer;transform:translate(-50%,-50%);transition:transform 0.15s;}\n.map-alert-dot:hover{transform:translate(-50%,-50%) scale(1.6);z-index:10;}\n.map-ripple{position:absolute;inset:-4px;border-radius:50%;border:2px solid currentColor;opacity:0;animation:ripOut 2.2s ease-out infinite;}\n@keyframes ripOut{0%{transform:scale(0.7);opacity:0.8;}100%{transform:scale(2.2);opacity:0;}}\n.map-tt{position:absolute;background:rgba(7,9,13,0.96);border:1px solid var(--border2);border-radius:6px;padding:8px 11px;font-size:10px;pointer-events:none;backdrop-filter:blur(14px);display:none;z-index:20;min-width:160px;font-family:'DM Mono',monospace;line-height:1.5;}\n.map-overlay{position:absolute;bottom:7px;left:7px;background:rgba(7,9,13,0.88);border:1px solid var(--border);border-radius:6px;padding:6px 9px;font-size:9px;backdrop-filter:blur(8px);}\n.ml-item{display:flex;align-items:center;gap:5px;color:var(--text2);margin-bottom:2px;}\n.ml-dot{width:6px;height:6px;border-radius:50%;}\n\n/* CHART TT */\n.chart-tt{position:absolute;background:rgba(7,9,13,0.96);border:1px solid var(--border2);border-radius:7px;padding:9px 12px;font-size:10px;pointer-events:none;backdrop-filter:blur(14px);display:none;z-index:50;min-width:175px;}\n.tt-head{font-size:8.5px;color:var(--text3);font-family:'DM Mono',monospace;margin-bottom:5px;letter-spacing:0.1em;text-transform:uppercase;}\n.tt-row{display:flex;align-items:center;gap:6px;margin-bottom:3px;font-size:10.5px;}\n.tt-dot{width:5px;height:5px;border-radius:50%;flex-shrink:0;}\n.tt-lbl{color:var(--text2);flex:1;}\n.tt-val{font-family:'DM Mono',monospace;font-weight:600;}\n\n/* TOAST */\n.toast-container{position:fixed;top:60px;right:18px;z-index:800;display:flex;flex-direction:column;gap:7px;pointer-events:none;}\n.toast{background:var(--panel2);border:1px solid var(--border2);border-radius:8px;padding:10px 14px;font-size:11.5px;max-width:290px;pointer-events:all;animation:tIn .32s cubic-bezier(.4,0,.2,1) both;display:flex;align-items:flex-start;gap:9px;cursor:pointer;}\n@keyframes tIn{from{transform:translateX(110%);opacity:0;}to{transform:none;opacity:1;}}\n.toast-out{animation:tOut .28s ease both;}\n@keyframes tOut{to{transform:translateX(110%);opacity:0;}}\n.t-icon{font-size:15px;flex-shrink:0;margin-top:1px;}\n.t-title{font-weight:600;color:var(--text);margin-bottom:1px;font-family:'Syne',sans-serif;font-size:11.5px;}\n.t-msg{color:var(--text2);font-size:10.5px;}\n\n/* MODAL */\n.modal-backdrop{position:fixed;inset:0;background:rgba(0,0,0,0.75);z-index:700;display:none;align-items:center;justify-content:center;backdrop-filter:blur(5px);}\n.modal-backdrop.open{display:flex;}\n.modal{background:var(--panel);border:1px solid var(--border2);border-radius:12px;width:560px;max-width:96vw;max-height:88vh;overflow:hidden;display:flex;flex-direction:column;animation:mIn .28s cubic-bezier(.4,0,.2,1) both;}\n@keyframes mIn{from{transform:scale(0.9);opacity:0;}to{transform:scale(1);opacity:1;}}\n.modal-header{display:flex;justify-content:space-between;align-items:center;padding:15px 18px;border-bottom:1px solid var(--border);flex-shrink:0;}\n.modal-title{font-family:'Syne',sans-serif;font-size:14px;font-weight:800;}\n.modal-close{width:26px;height:26px;border-radius:5px;background:var(--panel2);border:1px solid var(--border);display:flex;align-items:center;justify-content:center;cursor:pointer;font-size:12px;transition:all 0.13s;}\n.modal-close:hover{border-color:var(--red);color:var(--red);}\n.modal-body{padding:16px 18px;overflow-y:auto;}\n.modal-row{display:flex;justify-content:space-between;align-items:flex-start;padding:7px 0;border-bottom:1px solid var(--border);font-size:11.5px;gap:12px;}\n.modal-row:last-child{border:none;}\n.modal-key{color:var(--text2);font-family:'DM Mono',monospace;font-size:10px;flex-shrink:0;}\n.modal-val{font-weight:500;text-align:right;}\n\n/* SEARCH BAR */\n.search-bar{display:flex;align-items:center;gap:7px;background:var(--surface);border:1px solid var(--border);border-radius:6px;padding:5px 10px;transition:border-color 0.13s;}\n.search-bar:focus-within{border-color:var(--accent);}\n.search-bar input{background:none;border:none;color:var(--text);font-size:11px;font-family:'IBM Plex Sans',sans-serif;outline:none;width:145px;}\n.search-bar input::placeholder{color:var(--text3);}\n\n/* PANEL TABS */\n.ptabs{display:flex;gap:2px;}\n.ptab{padding:3px 9px;border-radius:4px;font-size:9.5px;font-weight:600;cursor:pointer;color:var(--text3);transition:all 0.13s;font-family:'DM Mono',monospace;user-select:none;}\n.ptab:hover{color:var(--text2);}\n.ptab.active{background:var(--panel2);color:var(--accent);}\n\n/* ALERT DROPDOWN */\n.alert-dropdown{position:absolute;top:40px;right:0;width:290px;background:var(--panel);border:1px solid var(--border2);border-radius:9px;box-shadow:0 16px 40px rgba(0,0,0,0.65);z-index:600;display:none;overflow:hidden;animation:dIn .2s ease both;}\n@keyframes dIn{from{transform:translateY(-8px);opacity:0;}to{transform:none;opacity:1;}}\n.alert-dropdown.open{display:block;}\n.ad-header{padding:10px 13px;border-bottom:1px solid var(--border);font-family:'Syne',sans-serif;font-size:11.5px;font-weight:700;display:flex;justify-content:space-between;}\n.ad-item{display:flex;gap:9px;padding:9px 13px;border-bottom:1px solid rgba(25,36,51,0.5);cursor:pointer;transition:background 0.1s;font-size:11px;}\n.ad-item:hover{background:rgba(255,255,255,0.02);}\n.ad-item:last-child{border:none;}\n.ad-icon{font-size:16px;}\n.ad-title{font-weight:600;margin-bottom:1px;font-size:11px;}\n.ad-meta{font-size:9.5px;color:var(--text2);font-family:'DM Mono',monospace;}\n\n/* FOOTER */\n.footer{background:var(--surface);border-top:1px solid var(--border);padding:7px 20px;display:flex;justify-content:space-between;align-items:center;font-size:9px;color:var(--text3);font-family:'DM Mono',monospace;}\n.footer-stats{display:flex;gap:12px;}\n.fstat{display:flex;align-items:center;gap:4px;}\n.fdot{width:5px;height:5px;border-radius:50%;}\n\n/* ─── REGULATORY FRAMEWORK MODULE STYLES ─── */\n.reg-hero{background:linear-gradient(135deg,rgba(123,82,200,0.15) 0%,rgba(34,114,195,0.1) 50%,rgba(0,0,0,0) 100%);border:1px solid rgba(123,82,200,0.2);border-radius:10px;padding:18px 20px;position:relative;overflow:hidden;}\n.reg-hero::before{content:'';position:absolute;top:-30px;right:-30px;width:180px;height:180px;background:radial-gradient(circle,rgba(123,82,200,0.12) 0%,transparent 70%);pointer-events:none;}\n.reg-hero-title{font-family:'Syne',sans-serif;font-size:18px;font-weight:800;color:var(--purple2);margin-bottom:4px;}\n.reg-hero-sub{font-size:11px;color:var(--text2);line-height:1.5;}\n.reg-kpi{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;}\n.reg-kpi-card{background:var(--panel);border:1px solid var(--border);border-radius:9px;padding:13px 15px;cursor:pointer;transition:transform 0.17s,box-shadow 0.17s;position:relative;overflow:hidden;}\n.reg-kpi-card:hover{transform:translateY(-3px);box-shadow:0 10px 25px rgba(0,0,0,0.4);}\n.reg-kpi-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;border-radius:9px 9px 0 0;background:linear-gradient(90deg,var(--purple),var(--blue2));}\n.rkpi-val{font-family:'Syne',sans-serif;font-size:22px;font-weight:800;color:var(--purple2);margin-bottom:4px;}\n.rkpi-label{font-size:9px;color:var(--text3);font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:0.1em;margin-bottom:8px;}\n.rkpi-sub{font-size:10px;color:var(--text2);}\n\n/* REGULATION CARD */\n.reg-card{background:var(--panel);border:1px solid var(--border);border-radius:9px;overflow:hidden;transition:border-color 0.18s,box-shadow 0.18s;cursor:pointer;}\n.reg-card:hover{border-color:var(--purple);box-shadow:0 0 0 1px rgba(123,82,200,0.15),0 8px 24px rgba(0,0,0,0.35);}\n.reg-card-header{padding:13px 15px;border-bottom:1px solid var(--border);display:flex;align-items:flex-start;gap:10px;}\n.reg-flag{font-size:22px;flex-shrink:0;}\n.reg-name{font-family:'Syne',sans-serif;font-size:12.5px;font-weight:700;margin-bottom:3px;}\n.reg-full{font-size:9.5px;color:var(--text2);line-height:1.4;}\n.reg-market{font-size:9px;font-family:'DM Mono',monospace;color:var(--text3);margin-top:4px;}\n.reg-card-body{padding:12px 15px;}\n.reg-meta-row{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;font-size:10.5px;}\n.reg-meta-key{color:var(--text2);}\n.reg-meta-val{font-family:'DM Mono',monospace;font-weight:600;}\n.reg-impact-bar{margin-top:8px;}\n.rib-label{font-size:8.5px;color:var(--text3);font-family:'DM Mono',monospace;margin-bottom:3px;display:flex;justify-content:space-between;}\n.rib-track{height:7px;background:var(--border);border-radius:4px;overflow:hidden;}\n.rib-fill{height:100%;border-radius:4px;transition:width 1s ease;}\n.reg-tags{display:flex;flex-wrap:wrap;gap:4px;margin-top:10px;}\n.reg-tag{font-size:8.5px;padding:2px 7px;border-radius:3px;font-family:'DM Mono',monospace;font-weight:600;}\n.reg-tag.green{background:rgba(34,201,122,0.1);color:var(--green2);border:1px solid rgba(34,201,122,0.15);}\n.reg-tag.red{background:rgba(217,64,64,0.1);color:var(--red2);border:1px solid rgba(217,64,64,0.15);}\n.reg-tag.yellow{background:rgba(244,162,51,0.1);color:var(--accent2);border:1px solid rgba(244,162,51,0.15);}\n.reg-tag.blue{background:rgba(58,159,232,0.1);color:var(--blue2);border:1px solid rgba(58,159,232,0.15);}\n.reg-tag.purple{background:rgba(123,82,200,0.1);color:var(--purple2);border:1px solid rgba(123,82,200,0.15);}\n.reg-tag.gray{background:rgba(106,145,176,0.1);color:var(--text2);border:1px solid rgba(106,145,176,0.15);}\n\n/* IMPACT HEATMAP */\n.heat-grid{display:grid;gap:3px;}\n.heat-cell{display:flex;align-items:center;justify-content:center;border-radius:4px;font-size:8.5px;font-weight:700;font-family:'DM Mono',monospace;cursor:pointer;transition:transform 0.12s;aspect-ratio:1.8;}\n.heat-cell:hover{transform:scale(1.08);z-index:2;}\n.heat-row-label{font-size:8.5px;color:var(--text3);font-family:'DM Mono',monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;padding-right:4px;display:flex;align-items:center;}\n.heat-col-label{font-size:7.5px;color:var(--text3);font-family:'DM Mono',monospace;text-align:center;white-space:nowrap;overflow:hidden;padding:2px 1px;}\n\n/* COMPLIANCE RING */\n.comp-ring{position:relative;width:76px;height:76px;flex-shrink:0;}\n.cr-svg{transform:rotate(-90deg);}\n.cr-track{fill:none;stroke:var(--border);stroke-width:8;}\n.cr-fill{fill:none;stroke-width:8;stroke-linecap:round;transition:stroke-dashoffset 1.3s ease;}\n.cr-center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;}\n.cr-pct{font-family:'Syne',sans-serif;font-weight:800;font-size:15px;line-height:1;}\n.cr-sub{font-size:7.5px;color:var(--text3);font-family:'DM Mono',monospace;}\n\n/* MARKET FLAG TABLE */\n.market-flag{font-size:16px;margin-right:5px;}\n.price-cell{font-family:'DM Mono',monospace;color:var(--accent);}\n.trend-up{color:var(--green2);font-family:'DM Mono',monospace;font-size:9.5px;}\n.trend-dn{color:var(--red2);font-family:'DM Mono',monospace;font-size:9.5px;}\n.vol-bar-inline{display:inline-block;width:50px;height:5px;background:var(--border);border-radius:3px;vertical-align:middle;overflow:hidden;margin-right:5px;}\n.vol-bar-fill{height:100%;border-radius:3px;background:var(--blue2);}\n\n/* RISK MATRIX */\n.risk-matrix-wrap{overflow-x:auto;}\n.risk-score-high{color:var(--red2);font-family:'DM Mono',monospace;font-weight:700;}\n.risk-score-med{color:var(--accent2);font-family:'DM Mono',monospace;font-weight:700;}\n.risk-score-low{color:var(--green2);font-family:'DM Mono',monospace;font-weight:700;}\n\n/* SELECT */\nselect{background:var(--surface);border:1px solid var(--border);border-radius:5px;color:var(--text2);font-size:10px;padding:4px 8px;font-family:'DM Mono',monospace;cursor:pointer;outline:none;}\nselect:focus{border-color:var(--accent);}\n\n/* REFRESH BTN */\n.refresh-btn{display:flex;align-items:center;gap:5px;background:var(--panel);border:1px solid var(--border2);border-radius:6px;padding:5px 11px;font-size:10px;color:var(--text2);cursor:pointer;font-family:'DM Mono',monospace;transition:all 0.13s;}\n.refresh-btn:hover{border-color:var(--accent);color:var(--accent);}\n.refresh-btn.spinning .ri{animation:spin 0.8s linear infinite;}\n@keyframes spin{to{transform:rotate(360deg);}}\n.ri{display:inline-block;}\n\n/* SECTION DIVIDER */\n.sec-div{height:1px;background:linear-gradient(90deg,transparent,var(--border),transparent);margin:4px 0;}\n\n\n/* ─── TRADING MODULE ─── */\n.trade-tab.active{background:rgba(34,201,122,0.13);color:var(--green2);border-color:rgba(34,201,122,0.22);}\n.trade-side-item.active{background:rgba(34,201,122,0.1);color:var(--green2);border-color:rgba(34,201,122,0.18);}\n.order-btn{width:100%;padding:11px;border-radius:8px;font-family:'Syne',sans-serif;font-weight:800;font-size:13px;cursor:pointer;border:none;transition:all 0.18s;letter-spacing:0.04em;user-select:none;}\n.order-btn.buy{background:linear-gradient(135deg,var(--green) 0%,var(--green2) 100%);color:#fff;}\n.order-btn.buy:hover{box-shadow:0 6px 20px rgba(34,201,122,0.4);transform:translateY(-2px);}\n.order-btn.sell{background:linear-gradient(135deg,var(--red) 0%,var(--red2) 100%);color:#fff;}\n.order-btn.sell:hover{box-shadow:0 6px 20px rgba(217,64,64,0.4);transform:translateY(-2px);}\n.order-btn:active{transform:translateY(0);}\n.order-type-btn{padding:5px 12px;border-radius:5px;font-size:10px;font-weight:700;cursor:pointer;border:1px solid var(--border);color:var(--text2);font-family:'DM Mono',monospace;transition:all 0.13s;user-select:none;}\n.order-type-btn.active{background:var(--panel2);color:var(--accent);border-color:var(--accent);}\n.price-input{width:100%;background:var(--surface);border:1px solid var(--border2);border-radius:6px;color:var(--text);font-family:'DM Mono',monospace;font-size:13px;padding:8px 12px;outline:none;transition:border-color 0.13s;}\n.price-input:focus{border-color:var(--accent);}\n.broker-card{background:var(--panel);border:1px solid var(--border);border-radius:10px;padding:14px;cursor:pointer;transition:all 0.18s;position:relative;overflow:hidden;}\n.broker-card:hover{border-color:var(--border2);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,0.4);}\n.broker-card.selected{border-color:var(--green2);background:rgba(34,201,122,0.06);}\n.broker-card.selected::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--green),var(--green2));}\n.broker-logo{width:36px;height:36px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:800;font-family:'Syne',sans-serif;flex-shrink:0;}\n.broker-name{font-family:'Syne',sans-serif;font-weight:700;font-size:12.5px;margin-bottom:2px;}\n.broker-spec{font-size:9.5px;color:var(--text2);font-family:'DM Mono',monospace;}\n.broker-rating{display:flex;gap:1px;margin-top:4px;}\n.star{color:var(--gold2);font-size:10px;}\n.order-book-row{display:flex;justify-content:space-between;align-items:center;padding:3px 8px;font-family:'DM Mono',monospace;font-size:10px;border-radius:3px;transition:background 0.1s;cursor:pointer;position:relative;}\n.order-book-row:hover{background:rgba(255,255,255,0.04);}\n.ob-bar{position:absolute;right:0;top:0;bottom:0;border-radius:3px;opacity:0.12;}\n.trade-stat{display:flex;flex-direction:column;gap:1px;}\n.ts-label{font-size:8.5px;color:var(--text3);font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:0.1em;}\n.ts-val{font-family:'DM Mono',monospace;font-weight:700;font-size:13px;}\n.positions-table td{padding:5px 8px;}\n.pnl-pos{color:var(--green2);font-family:'DM Mono',monospace;font-weight:700;}\n.pnl-neg{color:var(--red2);font-family:'DM Mono',monospace;font-weight:700;}\n.candle-up{fill:var(--green2);stroke:var(--green2);}\n.candle-dn{fill:var(--red2);stroke:var(--red2);}\n\n/* ─── TECHNICAL ANALYSIS ─── */\n.ta-tab.active{background:rgba(58,159,232,0.13);color:var(--blue2);border-color:rgba(58,159,232,0.22);}\n.ta-side.active{background:rgba(58,159,232,0.1);color:var(--blue2);border-color:rgba(58,159,232,0.18);}\n.indicator-pill{padding:3px 9px;border-radius:4px;font-size:9px;font-weight:700;font-family:'DM Mono',monospace;border:1px solid var(--border);color:var(--text3);cursor:pointer;transition:all 0.13s;user-select:none;}\n.indicator-pill:hover{border-color:var(--blue2);color:var(--blue2);}\n.indicator-pill.active{border-color:var(--blue2);color:var(--blue2);background:rgba(58,159,232,0.08);}\n.signal-card{padding:10px 12px;border-radius:7px;border:1px solid var(--border);background:var(--surface);}\n.signal-name{font-size:10px;color:var(--text2);font-family:'DM Mono',monospace;margin-bottom:3px;}\n.signal-val{font-family:'Syne',sans-serif;font-weight:800;font-size:15px;}\n.signal-action{font-size:8.5px;font-family:'DM Mono',monospace;font-weight:700;padding:2px 6px;border-radius:3px;margin-top:3px;display:inline-block;}\n.sig-buy{background:rgba(34,201,122,0.15);color:var(--green2);}\n.sig-sell{background:rgba(217,64,64,0.15);color:var(--red2);}\n.sig-hold{background:rgba(244,162,51,0.12);color:var(--accent2);}\n.oscillator-bar{height:8px;background:var(--border);border-radius:4px;overflow:hidden;position:relative;}\n.osc-fill{height:100%;border-radius:4px;transition:width 0.6s ease;}\n.osc-center{position:absolute;left:50%;top:0;bottom:0;width:1px;background:var(--border2);}\n\n/* ─── PUBLICATIONS ─── */\n.pub-card{background:var(--panel);border:1px solid var(--border);border-radius:10px;overflow:hidden;transition:all 0.18s;cursor:pointer;}\n.pub-card:hover{border-color:var(--border2);transform:translateY(-2px);box-shadow:0 8px 24px rgba(0,0,0,0.35);}\n.pub-banner{height:48px;display:flex;align-items:center;justify-content:center;font-family:'Syne',sans-serif;font-weight:800;font-size:13px;letter-spacing:0.02em;}\n.pub-body{padding:12px 14px;}\n.pub-title{font-family:'Syne',sans-serif;font-weight:700;font-size:11.5px;margin-bottom:4px;line-height:1.4;}\n.pub-meta{font-size:9.5px;color:var(--text2);font-family:'DM Mono',monospace;margin-bottom:8px;}\n.pub-desc{font-size:10.5px;color:var(--text2);line-height:1.5;margin-bottom:10px;}\n.pub-tag{font-size:8.5px;padding:2px 7px;border-radius:3px;font-family:'DM Mono',monospace;font-weight:600;}\n.article-row{display:flex;gap:10px;padding:10px 0;border-bottom:1px solid var(--border);cursor:pointer;transition:background 0.1s;}\n.article-row:hover{background:rgba(255,255,255,0.02);}\n.article-row:last-child{border:none;}\n.article-num{font-family:'Syne',sans-serif;font-weight:800;font-size:18px;color:var(--border2);width:28px;flex-shrink:0;}\n.article-title{font-size:11.5px;font-weight:600;margin-bottom:3px;line-height:1.4;}\n.article-meta{font-size:9.5px;color:var(--text2);font-family:'DM Mono',monospace;}\n\n/* ─── FAQ ─── */\n.faq-tab.active{background:rgba(212,162,42,0.13);color:var(--gold2);border-color:rgba(212,162,42,0.22);}\n.faq-side.active{background:rgba(212,162,42,0.1);color:var(--gold2);border-color:rgba(212,162,42,0.18);}\n.faq-item{border:1px solid var(--border);border-radius:8px;overflow:hidden;transition:border-color 0.2s;margin-bottom:6px;}\n.faq-item.open{border-color:var(--border2);}\n.faq-q{display:flex;align-items:center;justify-content:space-between;padding:13px 16px;cursor:pointer;font-weight:600;font-size:12.5px;user-select:none;transition:background 0.13s;}\n.faq-q:hover{background:rgba(255,255,255,0.02);}\n.faq-arrow{font-size:12px;color:var(--text3);transition:transform 0.25s;flex-shrink:0;}\n.faq-item.open .faq-arrow{transform:rotate(180deg);}\n.faq-a{max-height:0;overflow:hidden;transition:max-height 0.35s cubic-bezier(0.4,0,0.2,1);}\n.faq-a-inner{padding:0 16px 14px;font-size:11.5px;color:var(--text2);line-height:1.7;border-top:1px solid var(--border);}\n.faq-cat-btn{padding:5px 13px;border-radius:5px;font-size:10px;font-weight:600;cursor:pointer;border:1px solid var(--border);color:var(--text3);font-family:'DM Mono',monospace;transition:all 0.13s;user-select:none;}\n.faq-cat-btn:hover{border-color:var(--gold2);color:var(--gold2);}\n.faq-cat-btn.active{background:rgba(212,162,42,0.1);border-color:var(--gold2);color:var(--gold2);}\n\n/* ─── FUNDAMENTALS & SENTIMENT ─── */\n.fund-tab.active{background:rgba(30,207,176,0.13);color:var(--teal2);border-color:rgba(30,207,176,0.22);}\n.fund-side.active{background:rgba(30,207,176,0.1);color:var(--teal2);border-color:rgba(30,207,176,0.18);}\n.sentiment-gauge{position:relative;width:160px;height:90px;margin:0 auto;}\n.sentiment-needle{transform-origin:80px 80px;transition:transform 1.2s cubic-bezier(0.4,0,0.2,1);}\n.fund-metric{display:flex;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--border);}\n.fund-metric:last-child{border:none;}\n.fm-icon{font-size:18px;width:28px;text-align:center;flex-shrink:0;}\n.fm-label{font-size:11px;color:var(--text2);flex:1;}\n.fm-val{font-family:'DM Mono',monospace;font-weight:700;font-size:12px;}\n.fm-chg{font-size:9.5px;font-family:'DM Mono',monospace;}\n.news-sentiment-item{display:flex;align-items:flex-start;gap:9px;padding:9px 0;border-bottom:1px solid rgba(25,36,51,0.6);}\n.news-sentiment-item:last-child{border:none;}\n.ns-dot{width:8px;height:8px;border-radius:50%;flex-shrink:0;margin-top:3px;}\n.ns-title{font-size:11px;font-weight:600;margin-bottom:2px;}\n.ns-meta{font-size:9.5px;color:var(--text2);font-family:'DM Mono',monospace;}\n.sentiment-bar-row{display:flex;align-items:center;gap:8px;margin-bottom:5px;}\n.sentiment-label{font-size:10px;color:var(--text2);width:65px;flex-shrink:0;font-family:'DM Mono',monospace;}\n.sentiment-track{flex:1;height:8px;background:var(--border);border-radius:4px;overflow:hidden;}\n.sentiment-fill{height:100%;border-radius:4px;transition:width 0.9s ease;}\n.supply-demand-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;}\n.sd-box{background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:12px;}\n.sd-title{font-size:9px;color:var(--text3);font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:0.12em;margin-bottom:8px;}\n.sd-item{display:flex;justify-content:space-between;font-size:10.5px;margin-bottom:4px;}\n.macro-indicator{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;}\n.mi-card{background:var(--surface);border:1px solid var(--border);border-radius:7px;padding:10px;text-align:center;}\n.mi-val{font-family:'Syne',sans-serif;font-size:18px;font-weight:800;margin-bottom:2px;}\n.mi-label{font-size:8.5px;color:var(--text3);font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:0.1em;}\n\n/* ─── AI BUSINESS INTELLIGENCE MODULE ─── */\n.bi-tab.active{background:linear-gradient(135deg,rgba(232,135,58,0.15),rgba(217,64,64,0.12));color:var(--accent);border-color:rgba(232,135,58,0.35);}\n.bi-side-item.active{background:rgba(232,135,58,0.1);color:var(--accent);border-color:rgba(232,135,58,0.2);}\n.ai-prompt-area{background:rgba(7,16,10,0.95);border:1px solid var(--border2);border-radius:10px;padding:16px;position:relative;transition:border-color 0.2s;}\n.ai-prompt-area:focus-within{border-color:var(--accent);}\n.ai-textarea{width:100%;background:transparent;border:none;color:var(--text);font-family:'IBM Plex Sans',sans-serif;font-size:12.5px;resize:none;outline:none;min-height:80px;line-height:1.6;}\n.ai-textarea::placeholder{color:var(--text3);}\n.ai-run-btn{background:linear-gradient(135deg,var(--accent) 0%,var(--red) 100%);color:#fff;border:none;border-radius:8px;padding:10px 22px;font-family:'Syne',sans-serif;font-weight:800;font-size:12px;cursor:pointer;transition:all 0.18s;letter-spacing:0.04em;display:flex;align-items:center;gap:8px;}\n.ai-run-btn:hover{box-shadow:0 6px 24px rgba(232,135,58,0.45);transform:translateY(-2px);}\n.ai-run-btn:disabled{opacity:0.5;cursor:not-allowed;transform:none;box-shadow:none;}\n.ai-run-btn .spin{display:inline-block;animation:spin 1s linear infinite;}\n@keyframes spin{from{transform:rotate(0deg);}to{transform:rotate(360deg);}}\n.segment-card{background:var(--panel);border:1px solid var(--border);border-radius:12px;padding:16px;position:relative;overflow:hidden;transition:all 0.2s;cursor:pointer;}\n.segment-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;}\n.segment-card:hover{transform:translateY(-3px);box-shadow:0 12px 32px rgba(0,0,0,0.4);}\n.segment-card.tier-1::before{background:linear-gradient(90deg,var(--green),var(--green2));}\n.segment-card.tier-2::before{background:linear-gradient(90deg,var(--accent),var(--accent2));}\n.segment-card.tier-3::before{background:linear-gradient(90deg,var(--blue),var(--blue2));}\n.segment-card.tier-4::before{background:linear-gradient(90deg,var(--purple),var(--purple2));}\n.seg-name{font-family:'Syne',sans-serif;font-weight:800;font-size:14px;margin-bottom:4px;}\n.seg-market{font-size:10px;color:var(--text2);font-family:'DM Mono',monospace;margin-bottom:10px;}\n.seg-roi{font-family:'Syne',sans-serif;font-size:28px;font-weight:800;line-height:1;}\n.seg-roi-label{font-size:9px;color:var(--text3);font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:.1em;}\n.seg-bar-row{display:flex;align-items:center;gap:8px;margin-bottom:4px;}\n.seg-bar-label{font-size:9px;color:var(--text3);width:72px;font-family:'DM Mono',monospace;text-transform:uppercase;}\n.seg-bar-track{flex:1;height:6px;background:var(--border);border-radius:3px;overflow:hidden;}\n.seg-bar-fill{height:100%;border-radius:3px;transition:width 1s ease;}\n.seg-tag{font-size:8px;padding:2px 7px;border-radius:3px;font-family:'DM Mono',monospace;font-weight:700;border:1px solid currentColor;display:inline-block;}\n.ai-response-block{background:rgba(7,16,10,0.95);border:1px solid var(--border);border-radius:10px;padding:16px;font-size:12px;line-height:1.8;color:var(--text2);}\n.ai-response-block strong{color:var(--text);font-weight:600;}\n.ai-response-block h3{color:var(--accent);font-family:'Syne',sans-serif;font-size:13px;font-weight:700;margin:12px 0 6px;}\n.ai-response-block ul{padding-left:18px;margin:4px 0;}\n.ai-response-block li{margin-bottom:3px;}\n.thinking-dots span{animation:blink 1.4s infinite both;}\n.thinking-dots span:nth-child(2){animation-delay:0.2s;}\n.thinking-dots span:nth-child(3){animation-delay:0.4s;}\n.matrix-cell{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:8px;border-radius:7px;border:1px solid var(--border);font-size:10px;text-align:center;cursor:pointer;transition:all 0.15s;}\n.matrix-cell:hover{border-color:var(--border2);transform:scale(1.03);}\n.heatmap-high{background:rgba(34,201,122,0.18);border-color:rgba(34,201,122,0.3);}\n.heatmap-med{background:rgba(244,162,51,0.12);border-color:rgba(244,162,51,0.25);}\n.heatmap-low{background:rgba(217,64,64,0.1);border-color:rgba(217,64,64,0.2);}\n.scenario-btn{padding:7px 14px;border-radius:6px;font-size:10px;font-weight:700;font-family:'DM Mono',monospace;cursor:pointer;border:1px solid var(--border);color:var(--text2);transition:all 0.13s;user-select:none;}\n.scenario-btn:hover{border-color:var(--accent);color:var(--accent);}\n.scenario-btn.active{background:rgba(232,135,58,0.12);border-color:var(--accent);color:var(--accent);}\n.stream-cursor{display:inline-block;width:2px;height:14px;background:var(--accent);animation:blink 0.8s infinite;vertical-align:middle;margin-left:2px;}\n.waterfall-bar{transition:height 0.8s cubic-bezier(0.4,0,0.2,1),background 0.3s;}\n.ai-chip{display:inline-flex;align-items:center;gap:4px;background:rgba(232,135,58,0.08);border:1px solid rgba(232,135,58,0.25);border-radius:20px;padding:3px 10px;font-size:9.5px;color:var(--accent);font-family:'DM Mono',monospace;}\n.prompt-suggestion{background:var(--panel);border:1px solid var(--border);border-radius:6px;padding:8px 12px;font-size:10.5px;cursor:pointer;transition:all 0.13s;color:var(--text2);}\n.prompt-suggestion:hover{border-color:var(--accent);color:var(--text);background:rgba(232,135,58,0.05);}\n.roi-gauge{position:relative;width:120px;height:60px;margin:0 auto;}\n.investment-table td, .investment-table th{padding:7px 10px;}\n\n\n/* ─── LIVE PRICE TICKER ─── */\n.price-ticker-wrap{background:rgba(5,15,10,0.98);border-bottom:1px solid rgba(34,201,122,0.15);overflow:hidden;height:34px;display:flex;align-items:center;position:relative;}\n.price-ticker-wrap::before{content:'';position:absolute;left:0;top:0;bottom:0;width:90px;background:linear-gradient(90deg,rgba(5,15,10,1) 0%,rgba(5,15,10,0) 100%);z-index:2;pointer-events:none;}\n.price-ticker-wrap::after{content:'';position:absolute;right:0;top:0;bottom:0;width:90px;background:linear-gradient(270deg,rgba(5,15,10,1) 0%,rgba(5,15,10,0) 100%);z-index:2;pointer-events:none;}\n.ticker-label{position:absolute;left:0;top:0;bottom:0;width:88px;display:flex;align-items:center;justify-content:center;background:rgba(34,201,122,0.12);border-right:1px solid rgba(34,201,122,0.15);z-index:3;flex-shrink:0;}\n.ticker-label span{font-size:8.5px;font-weight:700;color:#22C97A;font-family:'DM Mono',monospace;text-transform:uppercase;letter-spacing:.15em;}\n.ticker-track{display:flex;align-items:center;gap:0;animation:tickerScroll 90s linear infinite;padding-left:90px;white-space:nowrap;}\n.ticker-track:hover{animation-play-state:paused;}\n@keyframes tickerScroll{0%{transform:translateX(0);}100%{transform:translateX(-50%);}}\n.ticker-item{display:inline-flex;align-items:center;gap:7px;padding:0 18px;border-right:1px solid rgba(255,255,255,0.05);height:34px;flex-shrink:0;}\n.ticker-sp{font-size:9.5px;font-weight:700;color:var(--text2);font-family:'DM Mono',monospace;}\n.ticker-price{font-size:10px;font-weight:700;color:var(--text);font-family:'DM Mono',monospace;}\n.ticker-chg.up{color:#22C97A;font-size:9.5px;font-family:'DM Mono',monospace;}\n.ticker-chg.dn{color:#D94040;font-size:9.5px;font-family:'DM Mono',monospace;}\n.ticker-dot.up{width:5px;height:5px;border-radius:50%;background:#22C97A;flex-shrink:0;}\n.ticker-dot.dn{width:5px;height:5px;border-radius:50%;background:#D94040;flex-shrink:0;}\n\n@keyframes fadeIn{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}\n\ncanvas{display:block;width:100%!important;}\n.counting{display:inline-block;}\n.mono{font-family:'DM Mono',monospace;}\n\n/* REG FILTER BAR */\n.reg-filter-bar{display:flex;gap:6px;flex-wrap:wrap;align-items:center;}\n.rfbtn{padding:4px 11px;border-radius:5px;font-size:9.5px;font-weight:600;cursor:pointer;border:1px solid var(--border);color:var(--text3);font-family:'DM Mono',monospace;transition:all 0.13s;user-select:none;}\n.rfbtn:hover{border-color:var(--purple);color:var(--purple2);}\n.rfbtn.active{background:rgba(123,82,200,0.12);border-color:var(--purple);color:var(--purple2);}\n\n/* TIMELINE */\n.timeline{position:relative;padding-left:20px;}\n.timeline::before{content:'';position:absolute;left:7px;top:0;bottom:0;width:1px;background:var(--border);}\n.tl-item{position:relative;margin-bottom:12px;padding-left:16px;}\n.tl-dot{position:absolute;left:-13px;top:4px;width:8px;height:8px;border-radius:50%;border:2px solid var(--bg);}\n.tl-date{font-size:9px;color:var(--text3);font-family:'DM Mono',monospace;margin-bottom:2px;}\n.tl-title{font-size:11.5px;font-weight:600;margin-bottom:2px;}\n.tl-desc{font-size:10.5px;color:var(--text2);line-height:1.5;}\n\n/* PRICE IMPACT INDICATOR */\n.impact-indicator{display:flex;align-items:center;gap:5px;font-size:10px;}\n.impact-arrow{font-size:14px;}\n.impact-arrow.up{color:var(--red2);}\n.impact-arrow.dn{color:var(--green2);}\n.impact-arrow.neutral{color:var(--text3);}\n\n/* ANIMATED COUNTER REFRESH */\n@keyframes numFlash{0%{opacity:0.3;}100%{opacity:1;}}";
